    ["executed at",new Date().toISOString()]];
  var ns="http://www.w3.org/2000/svg",g=document.getElementById("out");
  for(var i=0;i<rows.length;i++){
    var a=document.createElementNS(ns,"text");a.setAttribute("x","24");a.setAttribute("y",String(160+i*38));
